#!/usr/bin/env python3
"""Deterministic generator and `--check` gate for `tests/README.md` shared fixture index."""

from __future__ import annotations

import argparse
import ast
import re
from dataclasses import dataclass
from pathlib import Path

GENERATED_BANNER = (
    "<!-- Generated by scripts/generate_test_fixture_index.py; do not edit manually. -->"
)
TS_EXPORT_RE = re.compile(
    r"^\s*export\s+(?:async\s+)?(?:function|const|class|type|interface)\s+([A-Za-z_][A-Za-z0-9_]*)",
    re.MULTILINE,
)


@dataclass(frozen=True, slots=True)
class FixtureEntry:
    """Indexed test fixture/helper file with discovered public symbols."""

    rel_path: str
    category: str
    summary: str
    symbols: tuple[str, ...]


def _first_summary_line(text: str, *, is_ts: bool) -> str:
    if is_ts:
        for line in text.splitlines()[:5]:
            stripped = line.strip()
            if stripped.startswith(("//", "/*", "*")):
                cleaned = stripped.lstrip("/* ").rstrip("*/ ").strip()
                if cleaned:
                    return cleaned[:100]
            elif stripped:
                break
        return "Vitest setup/mock helper module."
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return "Python test helper module."
    doc = ast.get_docstring(tree)
    if doc:
        return doc.splitlines()[0].strip()[:100]
    return "Python test helper module."


def _is_fixture_decorator(dec: ast.expr) -> tuple[bool, str | None]:
    target = dec.func if isinstance(dec, ast.Call) else dec
    name = ""
    if isinstance(target, ast.Name):
        name = target.id
    elif isinstance(target, ast.Attribute):
        name = target.attr
    if name != "fixture":
        return False, None
    scope: str | None = None
    if isinstance(dec, ast.Call):
        for kw in dec.keywords:
            if kw.arg == "scope" and isinstance(kw.value, ast.Constant):
                scope = str(kw.value.value)
    return True, scope


def _extract_python_symbols(text: str) -> tuple[str, ...]:
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return ()
    symbols: list[str] = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            is_fix = False
            scope: str | None = None
            for dec in node.decorator_list:
                matched, dec_scope = _is_fixture_decorator(dec)
                if matched:
                    is_fix = True
                    scope = dec_scope
                    break
            if is_fix:
                tag = f"@fixture({scope})" if scope else "@fixture"
                symbols.append(f"{node.name} [{tag}]")
            elif not node.name.startswith("_"):
                symbols.append(f"{node.name}()")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            symbols.append(node.name)
    return tuple(sorted(set(symbols)))


def _extract_ts_symbols(text: str) -> tuple[str, ...]:
    return tuple(sorted(set(TS_EXPORT_RE.findall(text))))


def _scan_files(repo_root: Path) -> list[tuple[str, Path]]:
    discovered: list[tuple[str, Path]] = []
    tests_dir = repo_root / "tests"
    if tests_dir.is_dir():
        for p in sorted(tests_dir.rglob("conftest.py")):
            discovered.append(("Pytest Fixtures (`conftest.py`)", p))
    fakes_dir = repo_root / "tests" / "unit" / "fakes"
    if fakes_dir.is_dir():
        for p in sorted(fakes_dir.glob("*.py")):
            if p.name != "__init__.py":
                discovered.append(("Unit Fakes (`tests/unit/fakes/`)", p))
    integ_dir = repo_root / "tests" / "integration"
    if integ_dir.is_dir():
        integ_files = sorted(
            {
                *integ_dir.glob("_*fixture*.py"),
                *(
                    [integ_dir / "_tc_socket_helpers.py"]
                    if (integ_dir / "_tc_socket_helpers.py").is_file()
                    else []
                ),
            }
        )
        for p in integ_files:
            discovered.append(("Integration Helpers (`tests/integration/`)", p))
    setup_dir = repo_root / "apps" / "web" / "src" / "__tests__" / "setup"
    if setup_dir.is_dir():
        for p in sorted(setup_dir.glob("*.ts")):
            discovered.append(("Vitest Setup & Mock Handlers (`apps/web/src/__tests__/setup/`)", p))
    return discovered


def collect_fixture_entries(repo_root: Path) -> list[FixtureEntry]:
    """Scan test fixture, fake, integration helper, and Vitest setup modules."""
    entries: list[FixtureEntry] = []
    for category, path in _scan_files(repo_root):
        if not path.is_file():
            continue
        rel = path.relative_to(repo_root).as_posix()
        text = path.read_text(encoding="utf-8", errors="replace")
        is_ts = path.suffix == ".ts"
        symbols = _extract_ts_symbols(text) if is_ts else _extract_python_symbols(text)
        summary = _first_summary_line(text, is_ts=is_ts)
        entries.append(
            FixtureEntry(rel_path=rel, category=category, summary=summary, symbols=symbols)
        )
    return entries


def render_fixture_index(repo_root: Path) -> str:
    """Render deterministic Markdown content for `tests/README.md`."""
    entries = collect_fixture_entries(repo_root)
    lines: list[str] = [
        GENERATED_BANNER,
        "",
        "# ORCIA Shared Test Fixtures, Fakes & Setup Helpers",
        "",
        "Consult this index before writing new fixtures or searching `tests/` (`R-READ-03`).",
        "Regenerate with `.venv/bin/python scripts/generate_test_fixture_index.py`.",
        "",
    ]
    current_cat: str | None = None
    for entry in entries:
        if entry.category != current_cat:
            current_cat = entry.category
            lines.extend(
                [
                    f"## {current_cat}",
                    "",
                    "| File | Summary | Key Symbols |",
                    "| :--- | :--- | :--- |",
                ]
            )
        sym_str = ", ".join(f"`{s}`" for s in entry.symbols[:10])
        if len(entry.symbols) > 10:
            sym_str += f", +{len(entry.symbols) - 10} more"
        if not sym_str:
            sym_str = "*(side-effect / setup)*"
        safe_summary = entry.summary.replace("|", "\\|")
        lines.append(f"| `{entry.rel_path}` | {safe_summary} | {sym_str} |")
    lines.append("")
    return "\n".join(lines)


def sync_or_check(repo_root: Path, *, check: bool) -> int:
    """Write `tests/README.md` or verify it matches the deterministic generator (`--check`)."""
    target = repo_root / "tests" / "README.md"
    rendered = render_fixture_index(repo_root)
    if check:
        if not target.is_file():
            print(
                "FAIL [fixture-index]: tests/README.md missing; "
                "run scripts/generate_test_fixture_index.py"
            )
            return 1
        current = target.read_text(encoding="utf-8")
        if current != rendered:
            print(
                "FAIL [fixture-index]: tests/README.md stale; "
                "run scripts/generate_test_fixture_index.py"
            )
            return 1
        print("PASS [fixture-index]: tests/README.md is up to date")
        return 0
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(rendered, encoding="utf-8")
    print(f"WROTE {target.relative_to(repo_root).as_posix()} ({len(rendered.encode('utf-8'))} B)")
    return 0


def main(argv: list[str] | None = None) -> int:
    """CLI entrypoint."""
    parser = argparse.ArgumentParser(
        description="Generate or verify tests/README.md fixture index."
    )
    parser.add_argument("--check", action="store_true", help="Fail if tests/README.md is stale.")
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parents[1],
        help="Repository root directory.",
    )
    args = parser.parse_args(argv)
    return sync_or_check(args.root.resolve(), check=bool(args.check))


if __name__ == "__main__":
    raise SystemExit(main())
